import {icon,table,pre,notice,chips,steps,download,options} from './ui.js';

const $=<T extends HTMLElement=HTMLElement>(s:string):T=>document.querySelector(s)!;
let builtins:Pack[]=[],fixtures:Fixtures={},mapping:Record<string,DeepnoteLink[]>={},store:Store=emptyStore(),questions:Question[]=[],current:Question;
let workspace:Workspace='code',search='',difficulty='All levels',technology='All topics',queue='All exercises';
let leftTab='Task',drawerTab='Results',labTab='Workspace',hintCount=0,revealed=false,selectedNode='',selectedCommit='',selectedFile='',mobilePanel='lab';
let editor:EditorHandle|null=null,editorEpoch=0,labEpoch=0,saveTimer:ReturnType<typeof setTimeout>|undefined,result:QueryResult|null=null,runEpoch=0,busy=false,storageBlocked=false;
let graphUndo:Graph[]=[],timerStart:number|null=null,timerElapsed=0,terminalResult:{value:unknown;output:string}|null=null;
let runStatuses:Record<string,string>={},runGrid:any[]=[],graphDrag=false;
const app=$('#app');
const draft=():Draft=>store.drafts[current.id]??{};
const code=():string=>draft().code??current.starter;
function toast(message:string,error=false):void{const host=$('#toast');host.textContent=message;host.classList.toggle('error',error);host.classList.add('visible');setTimeout(()=>host.classList.remove('visible'),5000);}
function persist(immediate=false):void{clearTimeout(saveTimer);const write=()=>{if(storageBlocked){$('#save-status').textContent='Recovery needed';return;}try{saveStore(store);$('#save-status').textContent='Saved on this device';}catch{storageBlocked=true;$('#save-status').textContent='Not saved - export backup';toast('Browser storage is unavailable or full. Export a backup from Settings before leaving.',true);}};if(immediate)write();else saveTimer=setTimeout(write,220);}
function patch(p:Partial<Draft>,immediate=false):void{markDraft(store,current.id,p);persist(immediate);}
function recalc():void{questions=[...builtins,...store.customPacks].flatMap(p=>p.questions).map(normalizeQuestion);}
function filtered():Question[]{return questions.filter(q=>q.workspace===workspace&&(!search||(q.title+' '+q.topic+' '+q.summary+' '+q.id).toLowerCase().includes(search.toLowerCase()))&&(difficulty==='All levels'||q.difficulty===difficulty)&&(technology==='All topics'||q.technology===technology)&&(queue==='All exercises'||queue==='Bookmarked'&&store.drafts[q.id]?.bookmark||queue==='Review queue'&&(store.drafts[q.id]?.status==='review'||store.drafts[q.id]?.confidence==='Review')||queue==='Unfinished'&&store.drafts[q.id]?.status!=='completed'));}
function graph():Graph{if(draft().graph)return clone(draft().graph!);return validateGraph(current.fixture?.graph??graphTemplate(current.template??(current.workspace==='model'?'model':'fabric')));}
function setGraph(g:Graph,remember=true):void{if(remember)graphUndo=[...graphUndo.slice(-19),graph()];patch({graph:validateGraph(g)},true);renderLab();}
function git():GitState{const s=draft().labState;if(s?.kind==='git'&&s.value?.commits){try{const v=clone(s.value);commitAt(v,headId(v));return v;}catch{toast('Saved virtual Git state is invalid. Reset this lab or export a backup.',true);}}return gitFixture(current.fixture?.git??'merge');}
function terminal():TerminalState{const s=draft().labState;return s?.kind==='terminal'&&s.value?.files?clone(s.value):terminalFixture(current.fixture?.shell??'bash');}
function shellHTML():void{
 app.innerHTML=`<a class="skip-link" href="#question-body">Skip to question</a><header class="topbar"><button class="icon-button mobile-menu" data-action="library" aria-label="Open exercise library">${icon('menu')}</button><a class="brand" href="#exercise=sql-paid-revenue" aria-label="CodeDELeet home"><span class="brand-mark">${icon('code')}</span><span>CodeDELeet<small>INTERVIEW WORKSTATION</small></span><span class="version">V2</span></a><nav class="workspace-nav" aria-label="Practice labs">${Object.entries(WORKSPACES).map(([key,w])=>`<button data-workspace="${key}" aria-label="${e(w.title)}" class="${key===workspace?'active':''}">${icon(w.icon)}<span>${w.title}</span></button>`).join('')}</nav><div class="top-actions"><span class="local-pill"><i></i>Local-first</span><button class="icon-button" data-action="settings" aria-label="Settings and backups">${icon('settings')}</button></div></header><div class="app-body"><aside class="library" aria-label="Exercise library"><div class="library-heading"><span class="eyebrow">YOUR PRACTICE</span><button class="icon-button mobile-menu" data-action="library" aria-label="Close library">${icon('close')}</button></div><h2 id="library-title">${e(WORKSPACES[workspace].title)}</h2><p class="muted library-subtitle">${e(WORKSPACES[workspace].subtitle)}</p><div class="search-wrap">${icon('search')}<input id="search" type="search" placeholder="Search exercises..." value="${e(search)}" aria-label="Search exercises"></div><div class="filter-row"><select id="difficulty" aria-label="Difficulty">${options(['All levels','Easy','Medium','Hard'],difficulty)}</select><select id="queue" aria-label="Practice queue">${options(['All exercises','Bookmarked','Review queue','Unfinished'],queue)}</select></div><select id="technology" aria-label="Technology">${options(['All topics',...new Set(questions.filter(q=>q.workspace===workspace).map(q=>q.technology!))],technology)}</select><div class="library-count" id="library-count"></div><div class="exercise-list" id="exercise-list" role="list"></div><div class="library-footer"><div id="progress-text"></div><div class="progress-track"><span id="progress-bar"></span></div><button class="text-button" data-action="export-backup">${icon('download')} Export my progress</button></div></aside><main class="main"><header class="exercise-header" id="exercise-header"></header><div class="mobile-tabs" aria-label="Mobile workspace"><button data-mobile="question">Question</button><button data-mobile="lab" class="active">Lab</button><button data-mobile="drawer">Results / notes</button></div><section class="workstation" id="workstation"><div class="top-split"><section class="question-panel"><nav class="panel-tabs" id="question-tabs" aria-label="Question information"></nav><div id="question-body" class="panel-scroll" tabindex="-1"></div></section><div class="separator vertical" id="column-separator" role="separator" tabindex="0" aria-label="Resize question and lab" aria-orientation="vertical" aria-valuemin="28" aria-valuemax="62"></div><section class="lab-panel"><div class="lab-toolbar" id="lab-toolbar"></div><div id="lab-content" class="lab-content"></div></section></div><div class="separator horizontal" id="drawer-separator" role="separator" tabindex="0" aria-label="Resize results drawer" aria-orientation="horizontal" aria-valuemin="120" aria-valuemax="520"></div><section class="drawer"><nav class="drawer-tabs" id="drawer-tabs" aria-label="Results and explanation"></nav><div class="drawer-body" id="drawer-body"></div></section></section><footer class="statusbar"><span id="save-status">Saved on this device</span><span>Ctrl + Enter: run &nbsp; &middot; &nbsp; Alt + arrows: navigate</span><span id="engine-status">No runtime loaded</span></footer></main></div>`;
 renderLibrary();renderHeader();renderQuestion();renderLab();renderDrawer();applyLayout();bindControls();
}
function renderLibrary():void{const list=filtered();$('#library-count').textContent=`${list.length} exercises`;$('#exercise-list').innerHTML=list.length?list.map(q=>{const d=store.drafts[q.id]??{};return `<button class="exercise-item ${q.id===current.id?'selected':''}" data-question="${q.id}" role="listitem" aria-current="${q.id===current.id?'true':'false'}"><span class="exercise-status ${d.status==='completed'?'done':''}">${d.status==='completed'?icon('check'):''}</span><span class="exercise-item-copy"><strong>${e(q.title)}</strong><span><b class="level ${q.difficulty.toLowerCase()}">${q.difficulty}</b><span>${e(q.technology)}</span></span></span>${d.bookmark?'<span class="tiny-bookmark">'+icon('bookmark')+'</span>':''}</button>`;}).join(''):'<div class="empty small">No exercises match these filters.</div>';const done=questions.filter(q=>store.drafts[q.id]?.status==='completed').length;$('#progress-text').innerHTML=`<strong>${done}</strong> of ${questions.length} marked complete`;$('#progress-bar').style.width=100*done/questions.length+'%';}
function labelMode():string{const q=current;if(q.executionMode==='execute')return q.engine==='sql'?'EXECUTE / DUCKDB-WASM':'EXECUTE / PYODIDE';if(q.renderer==='pyspark-editor')return 'GUIDED REVIEW / NO SPARK RUNTIME';if(q.renderer==='semantic-model')return 'TEACHING MODEL / DAX SUBSET';return `${q.executionMode?.toUpperCase()} / ${q.renderer==='terminal'?'VIRTUAL SHELL':q.renderer==='git-visual'?'VIRTUAL GIT':q.renderer==='config-editor'?'TEXT CHECKS':'FIXTURE'}`;}
function actionLabel():string{return busy?'Cancel':current.renderer==='git-visual'||current.renderer==='terminal'?'Check goal':current.executionMode==='execute'?'Run & test':current.renderer==='dag-editor'?'Simulate':current.renderer==='semantic-model'?'Evaluate':current.renderer==='config-editor'?'Analyze':'Record review';}
function renderHeader():void{const d=draft(),siblings=filtered(),i=siblings.findIndex(q=>q.id===current.id);$('#exercise-header').innerHTML=`<div class="exercise-title"><div class="breadcrumb">${e(WORKSPACES[current.workspace].title)} <span>/</span> ${e(current.technology)} <span class="level ${current.difficulty.toLowerCase()}">${current.difficulty}</span></div><h1>${e(current.title)}</h1><span class="mode-label">${e(labelMode())}</span></div><div class="exercise-actions"><button class="icon-button ${d.bookmark?'is-bookmarked':''}" data-action="bookmark" aria-label="Bookmark exercise" aria-pressed="${!!d.bookmark}">${icon('bookmark')}</button><button class="timer-button" data-action="timer" aria-label="Start or pause practice timer">${icon('clock')}<span id="timer-value">${clockText()}</span></button><div class="navigation-buttons"><button class="icon-button previous" data-action="previous" aria-label="Previous exercise" ${i<=0?'disabled':''}>${icon('chevron')}</button><span>${i>=0?i+1:'-'}/${siblings.length}</span><button class="icon-button" data-action="next" aria-label="Next exercise" ${i<0||i>=siblings.length-1?'disabled':''}>${icon('chevron')}</button></div><button class="primary run-button" data-action="run">${icon(busy?'close':'play')}<span>${actionLabel()}</span></button></div>`;}
function tabs(items:string[],active:string,attr:string):string{return items.map(x=>`<button ${attr}="${e(x)}" class="${x===active?'active':''}" aria-pressed="${x===active}">${e(x)}</button>`).join('');}
function renderQuestion():void{$('#question-tabs').innerHTML=tabs(['Task','Data','Schema','Hints'],leftTab,'data-left-tab');const q=current;let html='';
 if(leftTab==='Task')html=`<span class="eyebrow">THE CHALLENGE</span><p class="question-summary">${e(q.summary)}</p><h2>Your task</h2><p class="task-text">${e(q.task)}</p><h3>Acceptance criteria</h3><ul class="requirements">${q.requirements.map(r=>`<li>${e(r)}</li>`).join('')}</ul><details class="concept-details"><summary>Concept refresher</summary>${q.concept.map(c=>`<p>${e(c)}</p>`).join('')}</details><div class="question-meta">${chips([q.minutes+' min suggested',['high','essential'].includes(q.interviewPriority??'')?'Interview essential':'Practice'])}</div><div class="mini-callout">Try your own approach first. Data and schema are available before you reveal the explanation.</div>`;
 if(leftTab==='Data')html=dataPanel();
 if(leftTab==='Schema')html=schemaPanel();
 if(leftTab==='Hints')html=`<span class="eyebrow">A LITTLE HELP</span><h2>Work one step at a time</h2><p>Hints are optional. The reference solution stays closed.</p>${q.hints.slice(0,hintCount).map((h,i)=>notice('Hint '+(i+1),h)).join('')}<button class="secondary" data-action="hint" ${hintCount>=q.hints.length?'disabled':''}>${hintCount>=q.hints.length?'All hints shown':'Reveal next hint'}</button><h3>Interview follow-ups</h3>${(q.followUps??[]).map(f=>`<p class="follow-up">${e(f)}</p>`).join('')}`;
 $('#question-body').innerHTML=html;
}
function dataPanel():string{const q=current,f=q.fixture??{};let html='<span class="eyebrow">SMALL, DETERMINISTIC DATA</span><h2>Inspect the inputs</h2>';
 if(q.engine==='sql'||q.renderer==='semantic-model'){const names=q.renderer==='semantic-model'?['Sales','DimCustomer','DimProduct']:['customers','orders'];for(const name of names)html+=`<h3>${name} <span class="muted">${fixtures[name].rows.length} rows</span></h3>${table(fixtures[name].rows)}`;if(f.sqlTests)html+=`<details><summary>Expected result for the base fixture</summary>${table(f.sqlTests[0].rows,f.sqlTests[0].columns)}</details>`;}
 else if(q.pythonTests?.length)html+=q.pythonTests.map(t=>`<details open><summary>${e(t.label)}</summary><h4>Arguments</h4>${pre(t.args)}<h4>Expected return</h4>${pre(t.expected)}</details>`).join('');
 else if(f.tables){for(const [name,rows]of Object.entries(f.tables))html+=`<h3>${e(name)}</h3>${Array.isArray(rows)?table(rows):pre(rows)}`;if(f.expected)html+='<h3>Expected output</h3>'+table(f.expected);}
 else if(q.renderer==='terminal'){const t=terminal();for(const [path,content]of Object.entries(t.files))html+=`<details><summary>${e(path)}</summary>${pre(content)}</details>`;}
 else if(q.renderer==='git-visual'){const s=git();html+=notice('Virtual repository','All files, commits and references stay inside this exercise. No connection to GitHub or your filesystem.');html+=table(Object.entries(s.branches).map(([branch,commit])=>({branch,commit})));for(const [path,content]of Object.entries(s.files))html+=`<details><summary>${e(path)}</summary>${pre(content)}</details>`;}
 else if(f.tasks)html+='<h3>Observed task metrics</h3>'+table(f.tasks);
 else if(f.events)html+='<h3>Events (supplied evidence)</h3>'+table(f.events);
 else if(f.run_results)html+='<h3>Run results</h3>'+table(f.run_results.results);
 else html+=notice('Design / reasoning case','There is no hidden dataset. Use the task constraints and the evidence provided in the lab.');
 return html;
}
function schemaPanel():string{const q=current;let html='<span class="eyebrow">CONTRACT & GRAIN</span><h2>Know what a row means</h2>';
 if(q.engine==='sql'||q.renderer==='semantic-model'){for(const name of q.renderer==='semantic-model'?['Sales','DimCustomer','DimProduct']:['customers','orders'])html+=`<h3>${name}</h3>${table(fixtures[name].columns)}`;html+=notice('Grain',q.renderer==='semantic-model'?'Sales: one order line. Dimensions: one row per key.':'customers: one customer. orders: one order. Do not multiply rows accidentally.');}
 else if(q.fixture?.schema)html+=pre(q.fixture.schema);
 else if(q.renderer==='dag-editor'||q.renderer==='architecture-editor')html+=notice('Graph contract','Nodes have stable IDs, labels, roles and positions. Edges connect existing nodes. Cycles are rejected for DAG simulation. The Config tab edits the same graph as the canvas.');
 else if(q.renderer==='terminal')html+=notice('Pipeline contract',terminal().shell==='powershell'?'PowerShell uses objects. Import-Csv initially creates string-valued properties; numeric comparisons need an explicit cast.':'Bash uses text streams. The virtual shell implements a documented subset, not a host shell.');
 else if(q.renderer==='git-visual')html+=steps(['Working tree: editable files','Index: next commit snapshot','Commit: immutable tree + parent(s)','Branch: movable reference; HEAD is symbolic or detached']);
 else html+=notice('Interface contract',q.entrypoint?`Implement ${q.entrypoint} with the parameters shown in the starter. Return the expected data structure; do not mutate inputs.`:'This case is evidence-led review. State assumptions and validate the real platform separately.');
 return html;
}
function labTabs():string[]{switch(current.renderer){case 'git-visual':return ['Workspace','Files','Diff','Predict'];case 'terminal':return ['Workspace','Files'];case 'semantic-model':return ['Workspace','Model','Rows'];case 'dag-editor':return ['Workspace','Config','Code','Run grid'];case 'architecture-editor':return ['Workspace','Config','Script','Mermaid','Trade-offs'];case 'performance-investigation':return ['Workspace','Evidence','Code'];case 'pipeline-investigation':return ['Workspace','Artifacts','Code'];case 'config-editor':return ['Workspace','Evidence'];default:return ['Workspace',...(current.renderer==='pyspark-editor'?['Plan','Sample rows']:[])];}}
function renderLab():void{
 const epoch=++labEpoch;editorEpoch++;editor?.destroy();editor=null;
 if(!labTabs().includes(labTab))labTab='Workspace';
 $('#lab-toolbar').innerHTML=`<nav class="panel-tabs compact" aria-label="Specialist lab views">${tabs(labTabs(),labTab,'data-lab-tab')}</nav><div class="lab-tools"><button class="icon-button" data-action="focus" aria-label="Toggle focused lab" aria-pressed="${store.settings.focus}">${icon('layout')}</button><button class="text-button" data-action="reset-lab">Reset</button></div>`;
 const host=$('#lab-content'),q=current,r=q.renderer;
 if(r==='git-visual'){host.innerHTML=gitPanel();return;}
 if(r==='terminal'){host.innerHTML=terminalPanel();return;}
 if(r==='semantic-model'){
  if(labTab==='Workspace'){host.innerHTML=`<div class="semantic-summary"><div><span class="eyebrow">SALES TEACHING MODEL</span><strong id="kpi-value">${semanticKPI()}</strong><small>Current measure preview</small></div><div class="slicers"><label>Country<select id="country">${options(['All','Norway','Sweden','Denmark'],draft().country??'All')}</select></label><label>Category<select id="category">${options(['All','Hardware','Accessories'],draft().category??'All')}</select></label></div></div><div class="code-context"><span>${e(q.language)}</span><small>${e(q.engine==='dax-subset'?'DAX teaching subset - not Power BI':'Record your grain and relationship reasoning')}</small></div><div id="editor-host" class="editor-host"></div><div class="lab-footnote">${e(DAX_SUPPORT)}</div>`;mountCode(epoch);}
  else if(labTab==='Model')host.innerHTML=graphPanel(true);
  else host.innerHTML=`<div class="panel-scroll"><h3>Visible Sales rows</h3>${table(visibleRows('Sales',fixtures,graph(),{country:draft().country??'All',category:draft().category??'All'}))}<p class="muted">Change country/category in Workspace, or deactivate a relationship in Model.</p></div>`;
  return;
 }
 if(r==='dag-editor'||r==='architecture-editor'){
  if(labTab==='Workspace')host.innerHTML=graphPanel(false);
  else if(labTab==='Config')host.innerHTML=`<div class="config-graph"><div class="notice compact-notice"><strong>One source of truth</strong><p>This JSON and the canvas share the saved graph. Apply to validate IDs, edges and coordinates.</p></div><textarea id="graph-config" class="code-fallback" aria-label="Graph configuration JSON">${e(JSON.stringify(graph(),null,2))}</textarea><div class="inline-actions"><button class="primary" data-action="apply-graph">Apply graph configuration</button><button class="secondary" data-action="export-graph">Export JSON</button></div></div>`;
  else if(labTab==='Code'){host.innerHTML=codePanel('Illustrative source - simulation uses the graph configuration, not this code.');mountCode(epoch);}
  else if(labTab==='Run grid')host.innerHTML=`<div class="panel-scroll"><h3>Deterministic run grid</h3>${runGrid.length?table(runGrid):notice('No simulation yet','Run the graph to inspect states, attempts and fixture durations.')}<p class="muted">Durations are declared fixture values, not observed cloud performance.</p></div>`;
  else if(labTab==='Script')host.innerHTML=`<div class="config-graph"><div class="notice compact-notice"><strong>Original diagram script</strong><p>Use a[Label] -&gt; b[Label]. Applying updates the same saved graph and preserves existing node settings.</p></div><textarea id="diagram-script" class="code-fallback" aria-label="Original diagram script">${e(draft().diagram??toDiagram(graph()))}</textarea><div class="inline-actions"><button class="primary" data-action="apply-script">Apply diagram script</button><button class="secondary" data-action="export-svg">Export SVG</button></div></div>`;
  else if(labTab==='Mermaid')host.innerHTML=mermaidPanel();
  else host.innerHTML=`<div class="panel-scroll"><h3>Compare the design choices</h3>${q.fixture?.comparison?table(q.fixture.comparison):steps(q.visual?.steps??q.concept)}${q.fixture?.constraints?pre(q.fixture.constraints):''}${notice('Explain trade-offs','A connected diagram is not proof of production security, sizing, reliability or correctness.')}</div>`;
  return;
 }
 if(r==='performance-investigation'){
  if(labTab==='Code'){host.innerHTML=codePanel('Propose a change. No Spark cluster or performance predictor is running.');mountCode(epoch);}
  else if(labTab==='Evidence')host.innerHTML=`<div class="panel-scroll"><h3>Task-level evidence</h3>${table(q.fixture?.tasks??[])}<h3>Supplied plan excerpt</h3>${pre(q.fixture?.plan??'')}</div>`;
  else host.innerHTML=performancePanel();return;
 }
 if(r==='pipeline-investigation'){
  if(labTab==='Code'){host.innerHTML=codePanel('Suggested model repair - not compiled by dbt.');mountCode(epoch);}
  else if(labTab==='Artifacts')host.innerHTML=`<div class="panel-scroll"><h3>manifest.json (curated subset)</h3>${pre(q.fixture?.manifest)}<h3>run_results.json (curated subset)</h3>${pre(q.fixture?.run_results)}</div>`;
  else host.innerHTML=`<div class="panel-scroll"><div class="section-header"><span class="eyebrow">DBT RUN INVESTIGATION</span><span class="chip">Fixture evidence</span></div>${graphSVG(graph())}<h3>What failed, and what was skipped?</h3>${table(q.fixture?.run_results?.results??[])}<label class="stacked-label">Your diagnosis<textarea id="diagnosis" placeholder="Name the upstream failure and the downstream consequence...">${e(draft().diagnosis??'')}</textarea></label>${notice('Lineage is not a scheduler trace','The graph reflects the supplied manifest relationships; run status is supplied evidence. Edits do not regenerate dbt artifacts.')}</div>`;
  return;
 }
 if(r==='config-editor'&&labTab==='Evidence'){host.innerHTML=configEvidence();return;}
 if(r==='multi-choice-reasoning'){host.innerHTML=`<div class="panel-scroll"><span class="eyebrow">CHOOSE, THEN EXPLAIN</span><h2>Which diagnosis fits?</h2><div class="choice-list">${(q.fixture?.options??[]).map((o:any)=>`<label class="choice"><input type="radio" name="answer" value="${e(o.id)}" ${draft().answer===o.id?'checked':''}><span>${e(o.label)}</span></label>`).join('')}</div><label class="stacked-label">Reasoning<textarea id="diagnosis" placeholder="Explain why, and why not the other choices...">${e(draft().diagnosis??'')}</textarea></label></div>`;return;}
 if(r==='pyspark-editor'&&labTab==='Plan'){host.innerHTML=`<div class="panel-scroll"><h3>Illustrative transformation plan</h3>${steps(q.visual?.steps??[])}${pre(q.fixture?.plan)}${notice('Not a live physical plan',q.fixture?.planNotice??'This is a supplied plan sketch. It is not generated from your draft, and no Spark execution is claimed.')}</div>`;return;}
 if(r==='pyspark-editor'&&labTab==='Sample rows'){host.innerHTML=`<div class="panel-scroll">${dataPanel()}</div>`;return;}
 host.innerHTML=codePanel(r==='pyspark-editor'?'PySpark draft - sample rows and plan are supplied, not computed. Use Deepnote for an actual runtime.':r==='config-editor'?'Bounded text checks only. No terraform apply, kubectl, or Docker daemon.':q.executionMode==='review'?'Guided review - your reasoning is saved; no interpreter is claimed.':q.engine==='sql'?'Real SQL on small in-memory fixtures. First Run loads DuckDB-Wasm.':'Real Python in a disposable worker. First Run loads Pyodide.');mountCode(epoch);
}
function codePanel(text:string):string{return `<div class="code-context"><span>${e(current.language)}</span><small>${e(current.executionMode==='execute'?'Runtime loads on demand':'No remote execution')}</small></div><div id="editor-host" class="editor-host"></div><div class="lab-footnote">${e(text)}</div>`;}
async function mountCode(epoch:number):Promise<void>{const host=$('#editor-host');if(!host)return;const editId=++editorEpoch,qid=current.id;const h=await mountEditor(host,code(),current.language,value=>{if(current.id!==qid)return;patch({code:value,status:draft().status==='completed'?'completed':'in-progress'});},()=>void run());if(epoch!==labEpoch||editId!==editorEpoch){h.destroy();return;}editor=h;}
function semanticKPI():string{if(current.engine!=='dax-subset')return 'Grain first';try{return formatNumber(evaluateDax(code(),fixtures,graph(),{country:draft().country??'All',category:draft().category??'All'}).value);}catch{return 'Not evaluated';}}
function graphPanel(model:boolean):string{
 const g=graph(),n=g.nodes.find(x=>x.id===selectedNode),architecture=current.renderer==='architecture-editor';
 return `<div class="graph-workspace"><div class="graph-actions"><span class="eyebrow">${model?'RELATIONSHIPS & GRAIN':architecture?'YOUR DESIGN':'DEPENDENCY CANVAS'}</span><div><button class="text-button" data-action="undo-graph" ${graphUndo.length?'':'disabled'}>Undo</button><button class="text-button" data-action="layout-graph">Auto layout</button><button class="text-button" data-action="add-node">+ Node</button></div></div><div class="graph-canvas" id="graph-canvas">${graphSVG(g,selectedNode,runStatuses)}</div><div class="graph-inspector">${n?`<div class="node-fields"><label>Selected node<input id="node-label" value="${e(n.label)}" aria-label="Node label"></label><label>Role<input id="node-role" value="${e(n.role)}" aria-label="Node role"></label>${!model&&!architecture?`<label>Retries<select id="node-retries">${options(['0','1','2','3'],String(n.retries??0))}</select></label><label>Trigger rule<select id="node-trigger">${options(['all_success','all_done','one_success','none_failed_min_one_success'],n.triggerRule??'all_success')}</select></label><label class="checkbox-label"><input id="node-transient" type="checkbox" ${n.transient?'checked':''}>Transient failure</label><label class="checkbox-label"><input id="node-skip" type="checkbox" ${n.skip?'checked':''}>Skip task</label>`:''}<button class="text-button danger" data-action="delete-node">Remove node</button></div>`:`<p class="muted">Select or drag a node. Arrow keys move a selected node. Use Config for the shared JSON representation.</p>`}${model?`<label class="grain-label">Fact grain<select id="grain">${options(['not-selected','order','order-line','customer'],draft().grain??'not-selected')}</select></label>`:''}<div class="edge-list">${g.edges.map(edge=>`<div class="edge-row"><label class="checkbox-label"><input type="checkbox" data-edge-active="${e(edge.id)}" ${edge.active!==false?'checked':''}><span>${e(g.nodes.find(n=>n.id===edge.from)?.label??edge.from)} <b>&rarr;</b> ${e(g.nodes.find(n=>n.id===edge.to)?.label??edge.to)}</span></label>${current.template==='watermark'?`<select data-edge-condition="${e(edge.id)}" aria-label="Dependency condition">${options(['Succeeded','Failed','Completed','Skipped'],edge.condition??'Succeeded')}</select>`:''}<button class="icon-button" data-remove-edge="${e(edge.id)}" aria-label="Remove ${e(edge.from)} to ${e(edge.to)}">${icon('close')}</button></div>`).join('')}</div><div class="connect-row"><select id="edge-from" aria-label="Connect from">${options(g.nodes.map(n=>n.id),g.nodes[0]?.id??'')}</select><span>&rarr;</span><select id="edge-to" aria-label="Connect to">${options(g.nodes.map(n=>n.id),g.nodes[1]?.id??'')}</select><button class="secondary" data-action="connect-nodes">Connect</button></div></div></div>`;
}
function gitPanel():string{
 const s=git();if(labTab==='Predict')return gitPredictionPanel();if(labTab==='Diff')return `<div class="panel-scroll"><h3>Working tree &rarr; index</h3>${pre(gitDiff(s.index,s.files)||'No unstaged changes.')}<h3>Index &rarr; HEAD</h3>${pre(gitDiff(commitAt(s,headId(s)).tree,s.index)||'No staged changes.')}</div>`;
 if(labTab==='Files'){selectedFile=Object.hasOwn(s.files,selectedFile)?selectedFile:Object.keys(s.files)[0];return `<div class="virtual-file-view"><label>Working-tree file<select id="git-file">${options(Object.keys(s.files),selectedFile)}</select></label><textarea id="virtual-file" class="code-fallback" aria-label="Virtual Git working-tree file">${e(s.files[selectedFile]??'')}</textarea><div class="inline-actions"><button class="primary" data-action="save-git-file">Save working file</button><button class="secondary" data-action="stage-file">Stage this file</button><span class="muted">Saving changes the working tree, not the index.</span></div></div>`;}
 const refs=aheadBehind(s,s.branches.main??headId(s),s.tracking['origin/main']??headId(s));const c=s.commits.find(c=>c.id===selectedCommit);
 return `<div class="git-workspace"><div class="git-summary"><span class="chip">SIMULATION</span><strong>HEAD &rarr; ${e(s.head??'detached at '+headId(s))}</strong><span class="muted">main: ${refs.ahead} ahead / ${refs.behind} behind tracking</span></div><div class="git-graph">${gitGraphSVG(s,selectedCommit)}</div><div class="git-middle"><div class="commit-inspector">${c?`<span class="eyebrow">COMMIT ${e(c.id)}</span><strong>${e(c.message)}</strong><p>Parent${c.parents.length===1?'':'s'}: ${e(c.parents.join(', ')||'none')}</p><p>${e(Object.keys(c.tree).join(', '))}</p>`:`<span class="eyebrow">CONNECTED STATE</span><p>Click a commit to inspect its parents and snapshot. Run commands to move real simulated refs.</p>`}</div><div class="git-state-summary"><div><span>Working tree</span><strong>${Object.keys(s.files).length} files</strong></div><div><span>Index</span><strong>${Object.keys(s.index).length} files</strong></div><div><span>Commits</span><strong>${s.commits.length}</strong></div></div></div><div class="terminal-console" aria-live="polite">${s.history.length?s.history.slice(-12).map(x=>pre(x)).join(''):'<p>Virtual Git ready. Type <code>git status</code> or <code>git help</code>.</p>'}</div><form class="command-line" id="git-form"><label for="git-command">git &gt;</label><input id="git-command" autocomplete="off" spellcheck="false" placeholder="git status" aria-label="Virtual Git command"><button class="primary" type="submit">Run command</button></form><div class="lab-footnote">No host, GitHub or remote access. Merge conflicts are whole-file teaching conflicts; rebase supports linear history only.</div></div>`;
}
function terminalPanel():string{const s=terminal();if(labTab==='Files'){selectedFile=Object.hasOwn(s.files,selectedFile)?selectedFile:Object.keys(s.files)[0];return `<div class="virtual-file-view"><label>Virtual filesystem<select id="terminal-file">${options(Object.keys(s.files),selectedFile)}</select></label><textarea id="virtual-file" class="code-fallback" aria-label="Virtual shell file">${e(s.files[selectedFile]??'')}</textarea><div class="inline-actions"><button class="primary" data-action="save-terminal-file">Save virtual file</button><span class="muted">No access to your actual disk.</span></div></div>`;}
 return `<div class="terminal-workspace"><div class="terminal-heading"><label>Shell<select id="shell-select">${options(['bash','powershell'],s.shell)}</select></label><span class="chip">VIRTUAL FILESYSTEM</span><button class="text-button" data-action="open-git">Open Git Lab</button></div><div class="terminal-console" aria-live="polite">${s.history.length?s.history.map(h=>`<div class="console-entry ${h.ok?'':'console-error'}"><div class="console-command">${e(s.shell==='bash'?'$':'PS>')} ${e(h.command)}</div><span class="output-type">${e(h.type)}</span>${pre(h.output)}</div>`).join(''):`<h3>${s.shell==='bash'?'Bash text streams':'PowerShell object pipelines'}</h3><p>Practice against small local fixtures, with no operating-system access.</p><p>Type <code>${s.shell==='bash'?'help':'Get-Help'}</code> for the supported command vocabulary.</p>`}</div><form class="command-line" id="terminal-form"><label for="terminal-command">${s.shell==='bash'?'$':'PS&gt;'}</label><input id="terminal-command" autocomplete="off" spellcheck="false" aria-label="Virtual shell command" placeholder="${s.shell==='bash'?'cat pipeline.log':'Get-Content pipeline.log'}"><button type="submit" class="primary">Run command</button></form><div class="lab-footnote">${s.shell==='bash'?'Text-stream simulation. Literal grep, simple pipes and a small safe command vocabulary.':'Object-pipeline simulation. This is not a full PowerShell interpreter; formatting is not converted to text between stages.'}</div></div>`;
}
function performancePanel():string{const f=current.fixture??{},tasks=f.tasks??[],max=Math.max(1,...tasks.map((t:any)=>Number(t.duration_s)||0));return `<div class="panel-scroll"><div class="section-header"><span class="eyebrow">PERFORMANCE INVESTIGATOR</span><span class="chip">Supplied observation fixture</span></div><div class="metric-cards">${(Array.isArray(f.metrics)?f.metrics:Object.entries(f.metrics??{}).map(([label,value])=>({label,value}))).map((m:any)=>`<div><span>${e(m.label)}</span><strong>${e(m.value)}</strong></div>`).join('')}</div><h3>Task duration distribution</h3><div class="task-bars">${tasks.map((t:any)=>`<div><span>Task ${e(t.task)}</span><div><i style="width:${Math.max(2,100*Number(t.duration_s)/max)}%"></i></div><strong>${e(formatNumber(t.duration_s))} s</strong></div>`).join('')}</div><h3>Which explanation matches the evidence?</h3><div class="choice-list">${(f.diagnoses??[]).map((d:any)=>`<label class="choice"><input type="radio" name="diagnosis-choice" value="${e(d.id)}" ${draft().answer===d.id?'checked':''}><span>${e(d.label)}</span></label>`).join('')}</div><label class="stacked-label">What would you inspect next?<textarea id="diagnosis" placeholder="Name the next metric or plan detail, and one trade-off...">${e(draft().diagnosis??'')}</textarea></label><p class="muted">The chart visualizes supplied measurements. It does not predict the effect of changing partitions or cluster size.</p></div>`;}
function configEvidence():string{const f=current.fixture??{};return `<div class="panel-scroll">${notice('Supplied evidence, not regenerated output','Editing your draft does not run a cloud provider, rebuild an image, replan resources or update this evidence.')}${f.graph?graphSVG(validateGraph(f.graph)):''}${f.events?'<h3>Events</h3>'+table(f.events):''}${f.logs?'<h3>Logs</h3>'+pre(f.logs):''}${f.plan?'<h3>Plan JSON</h3>'+pre(f.plan):''}${f.layers?'<h3>Layer cache evidence</h3>'+table(f.layers):''}</div>`;}
function mermaidPanel():string{return `<div class="mermaid-workspace"><div class="notice compact-notice"><strong>Mermaid preview (optional)</strong><p>Flowchart, ER and architecture-beta syntax can be rendered on demand. Rendering loads a pinned library; the offline canvas remains available.</p></div><textarea id="mermaid-source" class="code-fallback" aria-label="Mermaid source">${e(draft().mermaid??toMermaid(graph()))}</textarea><div class="inline-actions"><button class="primary" data-action="render-mermaid">Render Mermaid</button><button class="secondary" data-action="export-mermaid">Export .mmd</button></div><div id="mermaid-output" class="mermaid-output"></div></div>`;}
function renderDrawer():void{
 $('#drawer-tabs').innerHTML=`<div>${tabs(['Results','Explanation','Visual','Deepnote','Notes','History'],drawerTab,'data-drawer-tab')}</div><button class="icon-button" data-action="collapse-drawer" aria-label="${store.settings.drawerCollapsed?'Expand':'Collapse'} results drawer" aria-expanded="${!store.settings.drawerCollapsed}">${icon('chevron')}</button>`;
 const host=$('#drawer-body');
 if(drawerTab==='Results')host.innerHTML=resultPanel();
 else if(drawerTab==='Explanation')host.innerHTML=explanationPanel();
 else if(drawerTab==='Visual')host.innerHTML=visualPanel();
 else if(drawerTab==='Deepnote')host.innerHTML=deepnotePanel();
 else if(drawerTab==='Notes')host.innerHTML=`<div class="notes-panel"><div><span class="eyebrow">YOUR WORKING MEMORY</span><span class="muted">Private to this browser; included in your backup.</span></div><textarea id="notes" placeholder="Write the invariant, the mistake to avoid, or your interview explanation..." aria-label="Personal exercise notes">${e(draft().notes??'')}</textarea><div class="notes-settings"><label>Status<select id="status">${options(['not-started','in-progress','completed','review'],draft().status??'not-started')}</select></label><label>Confidence<select id="confidence">${options(['New','Learning','Review','Confident'],draft().confidence??'New')}</select></label></div></div>`;
 else host.innerHTML=`<div class="history-panel">${draft().attempts?.length?[...draft().attempts!].reverse().map(a=>`<details class="history-entry"><summary><span class="result-dot ${a.passed===true?'pass':a.passed===false?'fail':'review'}"></span><time>${e(new Date(a.at).toLocaleString())}</time><strong>${e(a.kind)}</strong><span>${e(a.summary)}</span></summary>${a.code?pre(a.code):'<p>No code snapshot for this command-based attempt.</p>'}</details>`).join(''):notice('No attempts yet','Runs, simulations and reviews are recorded here. A review is not marked as executed code.')}</div>`;
}
function resultPanel():string{if(!result)return `<div class="result-empty"><span class="empty-icon">${icon('play')}</span><div><h3>Your next attempt starts here</h3><p>Inspect the question, try a solution, then <strong>${e(actionLabel())}</strong>. Explanation stays closed until you choose it.</p></div></div>`;const r=result,checks=r.checks??[],passed=checks.filter(c=>c.passed).length;
 return `<div class="result-header"><span class="result-state ${r.error?'error':checks.length&&passed<checks.length?'attention':'success'}">${r.error?'NOT EXECUTED / ERROR':checks.length?`${passed} / ${checks.length} checks`:'Review recorded'}</span><span>${e(r.engine)}</span><span class="muted">${r.mode==='execute'?Math.round(r.elapsedMs)+' ms including adapter work':e(r.mode??'review')}</span></div>${r.error?notice('Attempt could not complete',r.error,'error'):''}${r.notice?`<p class="result-notice">${e(r.notice)}</p>`:''}${checks.length?`<div class="checks">${checks.map(c=>`<details class="check-item ${c.passed?'pass':'fail'}"><summary><span>${c.passed?'&#10003;':'&#215;'}</span>${e(c.label)}</summary><p>${e(c.detail)}</p></details>`).join('')}</div>`:''}${r.rows.length?table(r.rows,r.columns):''}${r.output?pre(r.output):''}${r.truncated?notice('Display capped','Only the first 200 rows are shown.'):''}`;
}
function explanationPanel():string{const q=current;if(!revealed)return `<div class="reveal-card"><span class="eyebrow">LEARN AFTER YOUR ATTEMPT</span><h3>Keep the answer out of sight until you are ready.</h3><p>Revealing does not overwrite your draft or mark the exercise as solved.</p><button class="secondary" data-action="reveal">Reveal explanation and reference</button></div>`;
 return `<div class="explanation-grid"><section><span class="eyebrow">WHY THIS WORKS</span><p>${e(q.explanation)}</p><h4>Self-review checklist</h4>${(q.rubric??q.requirements).map((r,i)=>`<label class="rubric-item"><input type="checkbox" data-rubric="${i}" ${(draft().rubric??[]).includes(String(i))?'checked':''}><span>${e(r)}</span></label>`).join('')}<h4>Official references</h4><div class="source-links">${q.sources.map(s=>`<a href="${e(s.url)}" target="_blank" rel="noopener noreferrer">${e(s.label)} &nearr;</a>`).join('')}</div></section><section><div class="section-header"><span class="eyebrow">REFERENCE APPROACH</span><button class="text-button" data-action="compare">Compare with my draft</button></div>${pre(q.solution)}<div id="comparison"></div></section></div>`;
}
function visualPanel():string{let html=`<div class="visual-panel"><span class="eyebrow">MAKE THE CONCEPT VISIBLE</span>${steps(current.visual?.steps??current.concept)}${current.visual?.detail?`<p>${e(current.visual.detail)}</p>`:''}`;if(['dag-editor','architecture-editor','semantic-model'].includes(current.renderer!))html+=graphSVG(graph(),selectedNode,runStatuses);if(current.renderer==='git-visual')html+=gitGraphSVG(git(),selectedCommit);if(current.renderer==='pyspark-editor')html+=`<h3>Expected sample output</h3>${table(current.fixture?.expected??[])}${pre(current.fixture?.plan)}`;return html+'</div>';}
function deepnotePanel():string{const links=validDeepnoteLinks(current,store.settings.deepnoteMap??{}),refs=[...(current.deepnoteLinks??[]),...(mapping[current.id]??[])];return `<div class="deepnote-panel"><div><span class="eyebrow">OPTIONAL COMPANION</span><h3>Continue in a notebook</h3><p>CodeDELeet keeps your draft and progress here. Deepnote is a separate environment; nothing is silently uploaded or executed.</p>${links.length?`<div class="companion-links">${links.map(l=>`<a class="secondary" href="${e(l.url)}" target="_blank" rel="noopener noreferrer">${e(l.label)} &nearr;</a>`).join('')}</div>`:notice('No notebook URL configured','The mapping keeps stable exercise IDs and notebook headings, but no project URL is invented. Add your own links in Settings.')}${refs.length?`<details><summary>Mapped notebook sections</summary>${refs.map(l=>`<p><strong>${e(l.notebook??l.label)}</strong><br>${e(l.exerciseRef??'')}</p>`).join('')}</details>`:''}<a class="text-button download-companion" href="./companion/Deepnote_Interview_Suite_v1_4.zip" download>Download the supplied 3-project notebook suite</a></div><div><h4>Use your current attempt</h4><p>Export your draft, open the relevant notebook, and run it in the appropriate environment. PySpark support depends on that notebook runtime.</p><button class="secondary" data-action="export-code">Export my draft</button>${safeDeepnoteURL(current.deepnoteEmbedUrl,true)?'<button class="secondary" data-action="embed-deepnote">Load configured public preview</button>':''}<div id="deepnote-embed"></div></div></div>`;}
function applyLayout():void{const {split,drawerHeight}=clampLayout(store.settings.split,store.settings.drawerHeight);const ws=$('#workstation');ws.style.setProperty('--split',split+'%');ws.style.setProperty('--drawer',Math.min(drawerHeight,Math.max(120,ws.clientHeight-160))+'px');ws.classList.toggle('drawer-collapsed',!!store.settings.drawerCollapsed);ws.classList.toggle('focus-lab',!!store.settings.focus);ws.dataset.mobile=mobilePanel;$('#column-separator').setAttribute('aria-valuenow',String(split));$('#drawer-separator').setAttribute('aria-valuenow',String(drawerHeight));editor?.refresh();}
function clockText():string{const secs=Math.floor((timerElapsed+(timerStart?Date.now()-timerStart:0))/1000);return `${String(Math.floor(secs/60)).padStart(2,'0')}:${String(secs%60).padStart(2,'0')}`;}
setInterval(()=>{const el=document.querySelector('#timer-value');if(el)el.textContent=clockText();},1000);
function navigate(id:string):void{$('#toast').classList.remove('visible');const q=questions.find(q=>q.id===id);if(!q)return;if(busy){cancelRuntime();busy=false;runEpoch++;}persist(true);const changedLab=workspace!==q.workspace;current=q;workspace=q.workspace;store.settings.lastQuestion=id;result=null;runGrid=[];runStatuses={};terminalResult=null;selectedNode='';selectedCommit='';selectedFile='';graphUndo=[];leftTab='Task';drawerTab='Results';labTab='Workspace';hintCount=0;revealed=false;timerStart=null;timerElapsed=0;if(changedLab){search='';difficulty='All levels';technology='All topics';queue='All exercises';}location.hash='exercise='+encodeURIComponent(id);shellHTML();persist();}
async function run():Promise<void>{
 if(busy){cancelRuntime();runEpoch++;busy=false;result={engine:'Cancelled',columns:[],rows:[],elapsedMs:0,error:'The worker was terminated. Your draft and notes are preserved.'};drawerTab='Results';store.settings.drawerCollapsed=false;renderHeader();renderDrawer();applyLayout();return;}
 const q=current,token=++runEpoch;busy=true;renderHeader();drawerTab='Results';store.settings.drawerCollapsed=false;result={engine:'Preparing attempt',columns:[],rows:[],elapsedMs:0,notice:'Preparing the selected execution or review mode.'};renderDrawer();applyLayout();
 try{
 let r:QueryResult;
 if(q.executionMode==='execute'){
  if(!store.settings.runtimeConsent){if(!confirm('Load a pinned browser runtime from jsDelivr? This can download substantial WebAssembly assets. Only run code you trust; do not put secrets in a browser code lab.'))throw Error('Runtime download was not authorized.');store.settings.runtimeConsent=true;persist(true);}
  const progress=(m:string)=>{if(token===runEpoch){$('#engine-status').textContent=m;result={engine:q.engine==='sql'?'DuckDB-Wasm loading':'Pyodide loading',columns:[],rows:[],elapsedMs:0,notice:m};renderDrawer();}};
  r=q.engine==='sql'?await executeSQL(q,code(),fixtures,progress):await executePython(q,code(),progress);
 }else if(q.renderer==='git-visual'){const checks=gitGoal(q,git());r={engine:'Deterministic Git simulation',mode:'simulate',columns:[],rows:[],elapsedMs:0,checks,notice:'These checks examine the actual virtual repository state, not your command text. No GitHub access.'};}
 else if(q.renderer==='terminal'){const state=terminal(),last=terminalResult;const checks=last?terminalGoal(q,last.value,last.output):[];r={engine:'Virtual '+state.shell,mode:'simulate',columns:[],rows:[],elapsedMs:0,checks,notice:last?'Checked the last command output against the exercise goal. No host commands ran.':'Run a shell command first; no output has been checked.'};}
 else if(q.renderer==='dag-editor'){runGrid=simulateDAG(graph());runStatuses=Object.fromEntries(runGrid.map(r=>[r.id,r.status]));const checks=q.fixture?.targetTask?[{label:'Join completes after an intentional skip',passed:runGrid.find(r=>r.id===q.fixture?.targetTask)?.status==='success',detail:'Choose a trigger rule compatible with the fixture skip.'}]:graphChecks(graph(),q.template??'pipeline');r={engine:'DAG teaching simulator',mode:'simulate',columns:['id','status','start','end','attempts','message'],rows:runGrid.map(x=>[x.id,x.status,x.start,x.end,x.attempts,x.message]),elapsedMs:0,checks,notice:'All times are deterministic fixture values. Airflow/ADF are not running. Structural repair and run success are separate observations.'};renderLab();}
 else if(q.renderer==='semantic-model'){
  if(q.engine==='dax-subset'){const ctx={country:draft().country??'All',category:draft().category??'All'},actual=evaluateDax(code(),fixtures,graph(),ctx);const expected=evaluateDax(q.solution,fixtures,graph(),ctx);r={engine:'Bounded DAX teaching interpreter',mode:'simulate',columns:['Measure','Value','Visible rows'],rows:[[actual.name,actual.value===null?'BLANK':actual.value,actual.rowCount]],elapsedMs:0,checks:[{label:'Matches reference measure in current filter context',passed:actual.value===expected.value,detail:'A current-context check is not a proof for every possible model or filter.'}],notice:'Only the displayed DAX subset and fixture model are supported. No Power BI engine is connected.'};const el=document.querySelector('#kpi-value');if(el)el.textContent=formatNumber(actual.value);}
  else r={engine:'Star-schema teaching checks',mode:'simulate',columns:[],rows:[],elapsedMs:0,checks:modelChecks(graph(),fixtures,draft().grain??''),notice:'Checks cover supplied keys, explicit active relationships and selected grain, not a production semantic model.'};
 }else if(q.renderer==='config-editor')r={engine:'Configuration text analyzer',mode:'analyze',columns:[],rows:[],elapsedMs:0,checks:configurationChecks(q,code()),notice:'Partial text checks, not YAML/HCL validation or vendor execution. The evidence fixture remains unchanged.'};
 else if(q.renderer==='performance-investigation'){const answer=q.fixture?.diagnoses?.find((x:any)=>x.id===draft().answer);r={engine:'Evidence-based Spark review',mode:'review',columns:[],rows:[],elapsedMs:0,checks:answer?[{label:'Diagnosis fits supplied evidence',passed:answer.correct===true,detail:'Explain the causal link and what you would measure next. This does not benchmark your proposed fix.'}]:[],notice:answer?'Recorded the selected diagnosis and your reasoning.':'Choose a diagnosis before checking it.'};}
 else if(q.renderer==='multi-choice-reasoning')r={engine:'Reasoning check',mode:'review',columns:[],rows:[],elapsedMs:0,checks:draft().answer?[{label:'Selected explanation',passed:draft().answer===q.fixture?.answer,detail:'Review the explanation after making your own case.'}]:[],notice:'No runtime execution. Reasoning is saved separately from the selected choice.'};
 else if(q.renderer==='architecture-editor')r={engine:'Conceptual architecture review',mode:'review',columns:[],rows:[],elapsedMs:0,checks:graphChecks(graph(),q.template??'fabric'),notice:'Graph checks assess roles and reachability only. They do not verify real licensing, cost, security or capacity.'};
 else r={engine:q.renderer==='pyspark-editor'?'PySpark guided review - NOT EXECUTED':'Guided interview review',mode:'review',columns:[],rows:[],elapsedMs:0,notice:'Your draft/reasoning was recorded. No automatic correctness claim: use the reference checklist, explain your choices, and validate with the appropriate external runtime.'};
 if(token!==runEpoch||q.id!==current.id)return;result=r;
 const checks=r.checks??[],passed=checks.length?checks.every(c=>c.passed):null;
 patch({status:draft().status==='completed'?'completed':'in-progress',attempts:[...(draft().attempts??[]),{at:new Date().toISOString(),kind:r.engine,passed,summary:checks.length?`${checks.filter(c=>c.passed).length}/${checks.length} checks`:'Review / no automated correctness claim',code:code().slice(0,30000)}].slice(-100)},true);
 }catch(error){if(token!==runEpoch)return;result={engine:'Attempt not completed',columns:[],rows:[],elapsedMs:0,error:(error as Error).message};patch({attempts:[...(draft().attempts??[]),{at:new Date().toISOString(),kind:'Error / not completed',passed:null,summary:(error as Error).message.slice(0,500)}].slice(-100)},true);}
 finally{if(token===runEpoch){busy=false;$('#engine-status').textContent=result?.error?'Runtime unavailable / attempt error':result?.engine??'Ready';renderHeader();renderDrawer();renderLibrary();}}
}
function exportBackup():void{persist(true);download('CodeDELeet-progress-'+new Date().toISOString().slice(0,10)+'.json',JSON.stringify(store,null,2));}
function settings():void{
 const dialog=$<HTMLDialogElement>('#modal');dialog.innerHTML=`<form method="dialog" class="dialog-header"><div><span class="eyebrow">LOCAL-FIRST WORKSPACE</span><h2>Settings & backups</h2></div><button class="icon-button" aria-label="Close settings">${icon('close')}</button></form><div class="dialog-body"><div class="settings-section"><h3>Your progress belongs to you</h3><p>Drafts, graphs, virtual repositories, notes, confidence and history live in this browser. A new domain or branch preview has separate storage: export here and import there.</p><div class="inline-actions"><button class="primary" id="settings-export">Export my backup</button><label class="secondary file-label">Merge backup<input type="file" id="backup-import" accept="application/json,.json"></label><button class="secondary" id="snapshot-export">Export pre-V2 snapshot</button></div>${storageBlocked?notice('Storage needs attention','Saving is blocked to avoid overwriting an unreadable backup. Download the raw stored value, then deliberately start a fresh local session.','error')+'<div class="inline-actions"><button class="secondary" id="raw-export">Download raw stored value</button><button class="secondary danger" id="storage-reset">Start fresh local storage</button></div>':''}</div><div class="settings-section"><h3>Content packs</h3><p>Import a versioned JSON pack. Built-in exercise IDs are protected. Updating a pack never detaches drafts or silently removes questions.</p><label class="secondary file-label">Import / update a pack<input type="file" id="pack-import" accept="application/json,.json"></label><div>${store.customPacks.map(p=>`<div class="custom-pack"><strong>${e(p.title)}</strong><span>v${p.version} &middot; ${p.questions.length} exercises</span><button class="text-button" data-export-pack="${e(p.id)}">Export</button></div>`).join('')}</div></div><div class="settings-section"><h3>Deepnote companion links</h3><p>Download the blank mapping, paste your own project/notebook URLs, then import it. Only explicit HTTPS Deepnote links are displayed; no API credentials are required.</p><div class="inline-actions"><button class="secondary" id="map-export">Download URL template</button><label class="secondary file-label">Import URL mapping<input type="file" id="map-import" accept="application/json,.json"></label></div></div><div class="settings-section"><h3>Runtime & layout</h3><p>SQL: DuckDB-Wasm ${RUNTIME_VERSIONS.duckdb}. Python: Pyodide ${RUNTIME_VERSIONS.pyodide}. Optional Mermaid: ${RUNTIME_VERSIONS.mermaid}. Downloads start only on explicit use. This page contains no service credentials or backend runner.</p><div class="inline-actions"><button class="secondary" id="runtime-reset">Reset workers & download consent</button><button class="secondary" id="layout-reset">Reset panel layout</button></div><p class="muted">Only run code you trust. Browser workers are not a security boundary against every form of hostile JavaScript/Python interoperability.</p></div><p class="muted">Version 2.0.0 &middot; Source, tests and migration notes are included in the delivery ZIP.</p></div>`;dialog.showModal();
 $('#settings-export').onclick=exportBackup;
 $('#snapshot-export').onclick=()=>{const raw=localStorage.getItem(STORAGE_KEY+'.pre-v2');if(raw)download('CodeDELeet-pre-v2.json',raw);else toast('No pre-upgrade value was present in this browser.');};
 if(storageBlocked){$('#raw-export').onclick=()=>download('CodeDELeet-raw-recovery.txt',localStorage.getItem(STORAGE_KEY)??'No value available.','text/plain');$('#storage-reset').onclick=()=>{if(confirm('Start fresh local storage? Download your raw backup first. This replaces the unreadable active value, not the pre-V2 snapshot.')){storageBlocked=false;persist(true);dialog.close();}};}
 $('#backup-import').onchange=()=>void readJSONFile($('#backup-import'),value=>{store=mergeStores(store,value,builtins);recalc();persist(true);dialog.close();navigate(current.id);toast('Backup merged. Newer drafts win; this device\'s settings are retained.');});
 $('#pack-import').onchange=()=>void readJSONFile($('#pack-import'),value=>{const plan=planPackImport(store.customPacks,value,builtins);store.customPacks=plan.packs;recalc();persist(true);dialog.close();shellHTML();toast(plan.summary);});
 $('#map-export').onclick=()=>download('deepnote-url-mapping.json',JSON.stringify({schemaVersion:1,links:mapping},null,2));
 $('#map-import').onchange=()=>void readJSONFile($('#map-import'),value=>{if(value.schemaVersion!==1||!value.links||typeof value.links!=='object'||Array.isArray(value.links))throw Error('Expected schemaVersion 1 with a links object.');const clean:Record<string,DeepnoteLink[]>={};for(const [id,links]of Object.entries(value.links)){if(!safeId(id)||!Array.isArray(links)||links.length>15)throw Error('Invalid mapping entry.');clean[id]=links.map(l=>{if(typeof l.url!=='string'||l.url&&!safeDeepnoteURL(l.url)||!['exercise','concept','mock','reference','project'].includes(l.type)||typeof l.label!=='string')throw Error('Unsafe or invalid Deepnote link.');return l;});}store.settings.deepnoteMap={...store.settings.deepnoteMap,...clean};persist(true);dialog.close();renderDrawer();toast('Deepnote links saved. Blank URLs remain hidden.');});
 $('#runtime-reset').onclick=()=>{cancelRuntime();runEpoch++;busy=false;store.settings.runtimeConsent=false;store.settings.pyodideConsent=false;persist(true);renderHeader();toast('Workers stopped. The next execution will ask before downloading.');};
 $('#layout-reset').onclick=()=>{store.settings.split=42;store.settings.drawerHeight=238;store.settings.drawerCollapsed=false;store.settings.focus=false;persist();applyLayout();toast('Panel layout reset.');};
 dialog.querySelectorAll<HTMLElement>('[data-export-pack]').forEach(b=>b.onclick=()=>{const p=store.customPacks.find(p=>p.id===b.dataset.exportPack);download(p!.id+'.json',JSON.stringify(p,null,2));});
}
async function readJSONFile(input:HTMLInputElement,apply:(value:any)=>void):Promise<void>{const file=input.files?.[0];if(!file)return;try{if(file.size>8_000_000)throw Error('Import limit: 8 MB.');const value=JSON.parse(await file.text());apply(value);}catch(error){toast((error as Error).message,true);}finally{input.value='';}}
async function renderMermaid():Promise<void>{const source=$<HTMLTextAreaElement>('#mermaid-source').value;if(source.length>15000){toast('Mermaid input limit: 15,000 characters.',true);return;}patch({mermaid:source},true);const host=$('#mermaid-output'),qid=current.id;host.textContent='Loading optional Mermaid renderer...';try{const url=`https://cdn.jsdelivr.net/npm/mermaid@${RUNTIME_VERSIONS.mermaid}/dist/mermaid.esm.min.mjs`;const m=(await import(/* @vite-ignore */ url)).default;m.initialize({startOnLoad:false,securityLevel:'strict',theme:'neutral',suppressErrorRendering:true,maxTextSize:15000,htmlLabels:false,flowchart:{htmlLabels:false}});const {svg}=await m.render(newId('diagram'),source);if(current.id===qid&&host.isConnected){const parsed=new DOMParser().parseFromString(svg,'image/svg+xml');if(parsed.querySelector('script,foreignObject,image'))throw Error('This preview disallows scripts, embedded HTML and external images. Use plain Mermaid labels.');host.innerHTML=svg;}}catch(error){if(host.isConnected)host.innerHTML=notice('Mermaid preview unavailable',(error as Error).message+' Your source is preserved. The offline canvas and .mmd export still work.','error');}}
function command(which:'git'|'terminal'):void{
 if(which==='git'){const input=$<HTMLInputElement>('#git-command'),text=input.value.trim();if(!text)return;const r=runGit(git(),text);patch({labState:{kind:'git',value:r.state},status:'in-progress'},true);renderLab();if(!r.ok)toast(r.output,true);$('#git-command')?.focus();}
 else {const input=$<HTMLInputElement>('#terminal-command'),text=input.value.trim();if(!text)return;const r=runTerminal(terminal(),text);patch({labState:{kind:'terminal',value:r.state},status:'in-progress'},true);terminalResult=r.ok?{value:r.value,output:r.output}:null;renderLab();$('#terminal-command')?.focus();}
 const console=document.querySelector('.terminal-console');if(console)console.scrollTop=console.scrollHeight;
}
function resetLab():void{if(!confirm('Reset the current code and lab state to the exercise fixture? Notes, bookmark, confidence and attempt history are preserved.'))return;patch({code:current.starter,graph:undefined,labState:undefined,diagram:undefined,mermaid:undefined,answer:undefined,diagnosis:undefined,grain:undefined},true);result=null;runStatuses={};runGrid=[];terminalResult=null;graphUndo=[];selectedNode='';selectedCommit='';renderLab();renderDrawer();}
function bindControls():void{
 $('#search').oninput=()=>{search=$<HTMLInputElement>('#search').value;renderLibrary();};
 app.onclick=(event)=>{const target=event.target as Element,button=target.closest<HTMLElement>('button,a');if(!button||button.hasAttribute('disabled'))return;
 if(button.dataset.question){navigate(button.dataset.question);document.body.classList.remove('library-open');return;}
 if(button.dataset.workspace){workspace=button.dataset.workspace as Workspace;technology='All topics';search='';difficulty='All levels';queue='All exercises';const q=filtered()[0];if(q)navigate(q.id);return;}
 if(button.dataset.leftTab){leftTab=button.dataset.leftTab;renderQuestion();return;}
 if(button.dataset.labTab){labTab=button.dataset.labTab;renderLab();return;}
 if(button.dataset.drawerTab){drawerTab=button.dataset.drawerTab;store.settings.drawerCollapsed=false;renderDrawer();applyLayout();persist();return;}
 if(button.dataset.mobile){mobilePanel=button.dataset.mobile;document.querySelectorAll('[data-mobile]').forEach(b=>b.classList.toggle('active',(b as HTMLElement).dataset.mobile===mobilePanel));applyLayout();return;}
 if(button.dataset.removeEdge){const g=graph();g.edges=g.edges.filter(x=>x.id!==button.dataset.removeEdge);setGraph(g);return;}
 const action=button.dataset.action;if(!action)return;
 try{switch(action){
 case 'settings':settings();break;
 case 'library':document.body.classList.toggle('library-open');break;
 case 'export-backup':exportBackup();break;
 case 'bookmark':patch({bookmark:!draft().bookmark},true);renderHeader();renderLibrary();break;
 case 'timer':if(timerStart){timerElapsed+=Date.now()-timerStart;timerStart=null;}else timerStart=Date.now();renderHeader();break;
 case 'previous':case 'next':{const list=filtered(),i=list.findIndex(q=>q.id===current.id),q=list[i+(action==='next'?1:-1)];if(q)navigate(q.id);break;}
 case 'run':void run();break;
 case 'hint':hintCount++;renderQuestion();break;
 case 'focus':store.settings.focus=!store.settings.focus;persist();applyLayout();renderLab();break;
 case 'collapse-drawer':store.settings.drawerCollapsed=!store.settings.drawerCollapsed;persist();renderDrawer();applyLayout();break;
 case 'reveal':revealed=true;renderDrawer();break;
 case 'compare':$('#comparison').innerHTML='<h4>Your draft (read-only comparison)</h4>'+pre(code());break;
 case 'reset-lab':resetLab();break;
 case 'layout-graph':setGraph(autoLayout(graph()));break;
 case 'undo-graph':{const previous=graphUndo.pop();if(previous)setGraph(previous,false);break;}
 case 'add-node':{const g=graph();if(g.nodes.length>=40)throw Error('Teaching limit: 40 nodes.');const id=newId('node');g.nodes.push({id,label:'New component',role:current.workspace==='model'?'dimension':'transform',x:35,y:55+Math.floor(g.nodes.length/3)*155,duration:3,retries:0});selectedNode=id;setGraph(g);break;}
 case 'delete-node':{const g=graph();g.nodes=g.nodes.filter(n=>n.id!==selectedNode);g.edges=g.edges.filter(x=>x.from!==selectedNode&&x.to!==selectedNode);selectedNode='';setGraph(g);break;}
 case 'connect-nodes':{const g=graph(),from=$<HTMLSelectElement>('#edge-from').value,to=$<HTMLSelectElement>('#edge-to').value;if(from===to)throw Error('Choose two different nodes.');if(g.edges.some(x=>x.from===from&&x.to===to))throw Error('That dependency already exists.');g.edges.push({id:newId('edge'),from,to,active:true,label:current.renderer==='semantic-model'?'1 : *':undefined});setGraph(g);break;}
 case 'apply-script':{const text=$<HTMLTextAreaElement>('#diagram-script').value;const g=parseDiagram(text,graph());patch({diagram:text});setGraph(g);toast('Diagram script applied to the graph.');break;}
 case 'apply-graph':setGraph(validateGraph(JSON.parse($<HTMLTextAreaElement>('#graph-config').value)));toast('Graph configuration applied.');break;
 case 'export-graph':download(current.id+'-graph.json',JSON.stringify(graph(),null,2));break;
 case 'export-svg':download(current.id+'-diagram.svg',graphSVG(graph()),'image/svg+xml');break;
 case 'render-mermaid':void renderMermaid();break;
 case 'export-mermaid':download(current.id+'.mmd',$<HTMLTextAreaElement>('#mermaid-source').value,'text/plain');break;
 case 'export-code':download(current.id+(/python|spark/i.test(current.language)?'.py':/sql/i.test(current.language)?'.sql':'.txt'),code(),'text/plain');break;
 case 'embed-deepnote':{const url=safeDeepnoteURL(current.deepnoteEmbedUrl,true);if(url)$('#deepnote-embed').innerHTML=`<iframe title="Configured Deepnote preview" src="${e(url)}" sandbox="allow-scripts allow-same-origin" referrerpolicy="no-referrer" loading="lazy"></iframe><p class="muted">Read-only companion preview; availability and authentication are controlled by Deepnote.</p>`;break;}
 case 'save-git-file':{const s=git();s.files[selectedFile]=$<HTMLTextAreaElement>('#virtual-file').value;patch({labState:{kind:'git',value:s}},true);toast('Working file saved. It is not staged.');break;}
 case 'stage-file':{const s=git();s.files[selectedFile]=$<HTMLTextAreaElement>('#virtual-file').value;const r=runGit(s,'git add "'+selectedFile.replace(/"/g,'')+'"');patch({labState:{kind:'git',value:r.state}},true);toast(r.output,!r.ok);break;}
 case 'save-terminal-file':{const s=terminal();s.files[selectedFile]=$<HTMLTextAreaElement>('#virtual-file').value;if(s.files[selectedFile].length>200000)throw Error('Virtual file limit exceeded.');patch({labState:{kind:'terminal',value:s}},true);toast('Virtual file saved.');break;}
 case 'open-git':navigate('v2-git-stage');break;
 case 'check-prediction':{const choices=gitPredictions();const correct=draft().gitPrediction===choices[0].id;$('#prediction-feedback').innerHTML=notice(correct?'Prediction matches':'Revisit the state transition',correct?'Now make the change in the live virtual repository. Prediction does not move any refs.':'Track HEAD, the branch ref, the index and the working tree independently.');break;}
 }}catch(error){toast((error as Error).message,true);}
 };
 app.onchange=(event)=>{const t=event.target as HTMLInputElement;
 try{if(t.id==='difficulty'){difficulty=t.value;renderLibrary();renderHeader();}
 else if(t.id==='queue'){queue=t.value;renderLibrary();renderHeader();}
 else if(t.id==='technology'){technology=t.value;renderLibrary();renderHeader();}
 else if(t.id==='country'||t.id==='category'){patch({[t.id]:t.value},true);renderLab();}
 else if(t.id==='grain'){patch({grain:t.value},true);}
 else if(t.id==='status'||t.id==='confidence'){patch({[t.id]:t.value},true);renderLibrary();}
 else if(t.name==='git-prediction')patch({gitPrediction:t.value},true);
 else if(t.name==='answer'||t.name==='diagnosis-choice')patch({answer:t.value},true);
 else if(t.dataset.rubric!==undefined){const values=new Set(draft().rubric??[]);t.checked?values.add(t.dataset.rubric):values.delete(t.dataset.rubric);patch({rubric:[...values]},true);}
 else if(t.dataset.edgeActive){const g=graph();g.edges.find(x=>x.id===t.dataset.edgeActive)!.active=t.checked;setGraph(g);}
 else if(t.dataset.edgeCondition){const g=graph();g.edges.find(x=>x.id===t.dataset.edgeCondition)!.condition=t.value;setGraph(g);}
 else if(t.id.startsWith('node-')){const g=graph(),n=g.nodes.find(n=>n.id===selectedNode);if(!n)return;if(t.id==='node-label')n.label=t.value;if(t.id==='node-role')n.role=t.value;if(t.id==='node-retries')n.retries=Number(t.value);if(t.id==='node-trigger')n.triggerRule=t.value;if(t.id==='node-transient')n.transient=t.checked;if(t.id==='node-skip')n.skip=t.checked;setGraph(g);}
 else if(t.id==='git-file'||t.id==='terminal-file'){selectedFile=t.value;renderLab();}
 else if(t.id==='shell-select'){const s=terminal();s.shell=t.value as 'bash'|'powershell';s.history=[];patch({labState:{kind:'terminal',value:s}},true);terminalResult=null;renderLab();}
 }catch(error){toast((error as Error).message,true);}
 };
 app.oninput=(event)=>{const t=event.target as HTMLTextAreaElement;if(t.id==='notes')patch({notes:t.value});if(t.id==='diagnosis')patch({diagnosis:t.value});if(t.id==='mermaid-source')patch({mermaid:t.value});if(t.id==='diagram-script')patch({diagram:t.value});};
 app.onsubmit=(event)=>{const form=event.target as HTMLFormElement;if(form.id==='git-form'||form.id==='terminal-form'){event.preventDefault();command(form.id==='git-form'?'git':'terminal');}};
 app.onpointerdown=event=>{const t=event.target as Element;const node=t.closest<SVGGElement>('[data-node]');if(!node||!t.closest('#graph-canvas'))return;const svg=node.ownerSVGElement!,g=graph(),n=g.nodes.find(n=>n.id===node.dataset.node);if(!n)return;const start={x:event.clientX,y:event.clientY,nx:n.x,ny:n.y},scale=svg.viewBox.baseVal.width/svg.getBoundingClientRect().width;graphDrag=false;const move=(ev:PointerEvent)=>{const dx=(ev.clientX-start.x)*scale,dy=(ev.clientY-start.y)*scale;if(Math.abs(dx)+Math.abs(dy)>3)graphDrag=true;n.x=Math.max(0,Math.min(4000,start.nx+dx));n.y=Math.max(0,Math.min(4000,start.ny+dy));node.setAttribute('transform',`translate(${n.x},${n.y})`);};const end=()=>{window.removeEventListener('pointermove',move);window.removeEventListener('pointerup',end);selectedNode=n.id;if(graphDrag)setGraph(g);else renderLab();};window.addEventListener('pointermove',move);window.addEventListener('pointerup',end,{once:true});event.preventDefault();};
 $('#column-separator').onpointerdown=ev=>resize(ev,'column');$('#drawer-separator').onpointerdown=ev=>resize(ev,'drawer');
 for(const [id,kind]of [['column-separator','column'],['drawer-separator','drawer']] as const)$('#'+id).onkeydown=ev=>{if(!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(ev.key))return;ev.preventDefault();if(kind==='column')store.settings.split=clampLayout(Number(store.settings.split??42)+(ev.key==='ArrowLeft'?-2:2),store.settings.drawerHeight).split;else store.settings.drawerHeight=clampLayout(store.settings.split,Number(store.settings.drawerHeight??238)+(ev.key==='ArrowDown'?-20:20)).drawerHeight;applyLayout();persist();};
}
// A single persistent delegated handler survives partial panel renders.
function selectSVG(event:Event):void{const target=event.target as Element,commit=target.closest<HTMLElement>('[data-commit]');if(commit){selectedCommit=commit.dataset.commit??'';renderLab();}}
app.addEventListener('click',selectSVG);
app.addEventListener('keydown',event=>{const t=event.target as HTMLElement;if(t.dataset.commit&&(event.key==='Enter'||event.key===' ')){event.preventDefault();selectedCommit=t.dataset.commit;renderLab();}if(t.dataset.node){if(event.key==='Enter'||event.key===' '){event.preventDefault();selectedNode=t.dataset.node;renderLab();}else if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(event.key)){event.preventDefault();const g=graph(),n=g.nodes.find(n=>n.id===t.dataset.node)!;n.x=Math.max(0,n.x+(event.key==='ArrowLeft'?-10:event.key==='ArrowRight'?10:0));n.y=Math.max(0,n.y+(event.key==='ArrowUp'?-10:event.key==='ArrowDown'?10:0));selectedNode=n.id;setGraph(g);}}});
function resize(event:PointerEvent,kind:'column'|'drawer'):void{event.preventDefault();const ws=$('#workstation'),rect=ws.getBoundingClientRect();document.body.classList.add('resizing');const move=(ev:PointerEvent)=>{if(kind==='column')store.settings.split=clampLayout(100*(ev.clientX-rect.left)/rect.width,store.settings.drawerHeight).split;else store.settings.drawerHeight=clampLayout(store.settings.split,rect.bottom-ev.clientY).drawerHeight;applyLayout();};const end=()=>{document.body.classList.remove('resizing');window.removeEventListener('pointermove',move);persist(true);};window.addEventListener('pointermove',move);window.addEventListener('pointerup',end,{once:true});}
window.addEventListener('keydown',event=>{if((event.ctrlKey||event.metaKey)&&event.key==='Enter'){if((event.target as HTMLElement).closest('.CodeMirror'))return;event.preventDefault();void run();}if(event.altKey&&['ArrowLeft','ArrowRight'].includes(event.key)){$<HTMLButtonElement>(`[data-action="${event.key==='ArrowLeft'?'previous':'next'}"]`)?.click();event.preventDefault();}});
window.addEventListener('resize',()=>{if(current)applyLayout();});
window.addEventListener('beforeunload',()=>{if(current)persist(true);});
window.addEventListener('hashchange',()=>{const id=new URLSearchParams(location.hash.slice(1)).get('exercise');if(id&&id!==current?.id)navigate(id);});
async function boot():Promise<void>{
 try{const manifest=await (await fetch('./packs/index.json')).json();builtins=await Promise.all(manifest.packs.map(async(path:string)=>validatePack(await (await fetch('./packs/'+path)).json())));fixtures=await (await fetch('./packs/fixtures.json')).json();mapping=(await (await fetch('./packs/deepnote-mapping.json')).json()).links??{};
 try{const original=localStorage.getItem(STORAGE_KEY);store=loadStore();if(original&&!JSON.parse(original).v2&&!localStorage.getItem(STORAGE_KEY+'.pre-v2'))localStorage.setItem(STORAGE_KEY+'.pre-v2',original);}catch{storageBlocked=true;store=emptyStore();}
 recalc();const id=new URLSearchParams(location.hash.slice(1)).get('exercise')??store.settings.lastQuestion;current=questions.find(q=>q.id===id)??questions[0];workspace=current.workspace;shellHTML();if(storageBlocked)toast('Stored progress could not be read. It has NOT been overwritten. Open Settings for recovery.',true);
 }catch(error){app.innerHTML=`<div class="boot-error"><h1>CodeDELeet could not start</h1><p>${e((error as Error).message)}</p><p>Serve the app using <code>npm start</code>, or deploy the built dist folder. Opening index.html directly as a file is not supported.</p></div>`;}
}
void boot();
function gitPredictions():{id:string;label:string}[]{const goal=current.fixture?.goal;const correct=goal==='fetch'?{id:'tracking',label:'Only the remote-tracking reference and fetched objects change.'}:goal==='rebase'?{id:'replay',label:'The feature changes are replayed onto main with new commit IDs.'}:goal==='staged-only'?{id:'index',label:'The commit contains the staged index, not every working-tree file.'}:goal==='rescue'?{id:'branch',label:'A new named branch points to the current commit and HEAD becomes attached.'}:{id:'parents',label:'A new commit records both parent histories; existing commits keep their IDs.'};return [correct,{id:'rewrite-all',label:'All existing commit IDs are rewritten and their snapshots are mutated.'},{id:'working-only',label:'Only the working files change; references and history never change.'}];}
function gitPredictionPanel():string{
 const choices=gitPredictions(),ordered=[choices[1],choices[0],choices[2]];let target=gitFixture(current.fixture?.git);
 const perform=(cmd:string)=>{const r=runGit(target,cmd);if(r.ok)target=r.state;};
 if(current.fixture?.goal==='merge'){perform('git merge feature');if(target.pendingMerge){target.files['pipeline.py']='print("ingest and validate")\n';perform('git add pipeline.py');perform('git commit -m "Resolved merge"');}}
 if(current.fixture?.goal==='rebase')perform('git rebase main');if(current.fixture?.goal==='fetch')perform('git fetch');if(current.fixture?.goal==='rescue')perform('git switch -c rescue');if(current.fixture?.goal==='staged-only'){perform('git add pipeline.py');perform('git commit -m "Validation"');}
 return `<div class="panel-scroll"><span class="eyebrow">PREDICT BEFORE YOU CHANGE IT</span><h3>What should change when you reach this goal?</h3><div class="choice-list">${ordered.map(c=>`<label class="choice"><input type="radio" name="git-prediction" value="${e(c.id)}" ${draft().gitPrediction===c.id?'checked':''}><span>${e(c.label)}</span></label>`).join('')}</div><div class="inline-actions" style="margin-top:12px"><button class="secondary" data-action="check-prediction">Check my prediction</button></div><div id="prediction-feedback"></div><details><summary>View target topology (not the command solution)</summary>${gitGraphSVG(target)}<p class="muted">Target state is a separate reference fixture. It never changes your live virtual repository. Branch and commit names may differ in an equivalent solution.</p></details></div>`;
}
